-- 047. Данияр: тексты под озвучку (проверка voice-checker 24.11): время словами («в половине шестого»),
-- без омографов все/всё, потом, уже. Меняется только текст; audio_url и условия реплик сохраняются.
begin;
update characters set fixed_questions = jsonb_set(fixed_questions, '{4,a}', to_jsonb('"— Да кто только не приходит. Поставщики, экспедиторы, кредиторы. Всех не упомнишь.\n(достаёт из сейфа толстую амбарную книгу)\nЖурнал КПП. На проходной пишут всех, кто входит. Берите, мне не жалко. Я, в отличие от некоторых, ничего не скрываю."'::json #>> '{}')) where id = 'a7955352-673d-5ff7-bfcc-506079544d1f';
update characters set fixed_questions = jsonb_set(fixed_questions, '{1,a}', to_jsonb('"— Дома. Один.\nС семи вечера... примерно. И до утра. Телевизор смотрел. Какая программа — не помню.\nЭто важно?"'::json #>> '{}')) where id = 'a7955352-673d-5ff7-bfcc-506079544d1f';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R14' then jsonb_set(r, '{text}', to_jsonb('"Данияр снимает очки. Кладёт на стол дужками вверх. Ровно.\n— Валентина Петровна сказала... Значит, всё.\nДа. Знал. С пятницы. Она запретила идти в милицию. Я согласился.\nСорок тысяч взял из кассы, которой официально нет. И вернул туда то, что раньше вывел.\nВ субботу в половине четвёртого был у неё. Когда телефон зазвонил. Номер на АОН сам видел. Переписал себе, цифра в цифру.\nОттуда с пакетом на Ташкентскую, на остановку. В половине шестого оставил под скамейкой.\nСтемнело. Парень... высокий, молодой. Спортивная куртка, ушанка. Лица не видел.\nДальше — на базу. Въехал без пяти шесть, выехал в десять минут восьмого. На КПП записано.\nВ половине восьмого вернулся к ней. До половины второго.\n(открывает нижний ящик) Копии всех купюр. Я не верил ни им, ни вам."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'a7955352-673d-5ff7-bfcc-506079544d1f';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R15' then jsonb_set(r, '{text}', to_jsonb('"Данияр смотрит на страницу блокнота. На лице что-то вроде облегчения.\n— Почерк Валентины Петровны. «Шестьдесят» — это тысяч. «Половина шестого, Ташкентская».\nВы, значит, всё поняли. (снимает очки)\nДа. С пятницы знал. В милицию не пошёл — она просила.\nСорок тысяч взял из «чёрной» кассы. Вернул туда то, что выводил.\nЭтот номер на АОН, в половине четвёртого... я своими глазами видел. Я там был, когда телефон зазвонил.\nВ половине шестого оставил пакет на остановке. Темно. Высокий, молодой. Спортивная куртка, ушанка. Лица — нет.\nДальше — база. Въехал без пяти шесть, выехал в десять минут восьмого, журнал КПП подтвердит.\nС половины восьмого до половины второго — опять у неё.\n(выдвигает ящик) Копии купюр. До единой. Возьмите."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'a7955352-673d-5ff7-bfcc-506079544d1f';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R16' then jsonb_set(r, '{text}', to_jsonb('"Данияр долго смотрит на строчку в журнале.\n— Двадцать восьмое октября. Десять минут пятого. Да.\nЯ был в кабинете. Фархад пришёл просить свою долю. Спокойно. Вежливо. В галстуке пришёл.\nВы знаете, что он сидел? В девяносто четвёртом. За товар их с Игорем фирмы — взял на себя. Полтора года.\nИгорь ему тогда обещал всё сохранить.\nА тут при мне: «Я тебя садиться не просил. Хочешь — иди завскладом».\nФархад ничего не ответил. Встал и ушёл. Молча.\n(пауза) Я тогда подумал: лучше бы кричал."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'a7955352-673d-5ff7-bfcc-506079544d1f';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R120' then jsonb_set(r, '{text}', to_jsonb('"Данияр читает. Пальцем ведёт по строчкам. Останавливается на своей фамилии.\n— Вторая. Да. Вторая. — Слишком быстро. — Как у многих. Тридцать восемь процентов населения. Примерно.\n(пауза)\n— Руки смотрите. Пожалуйста. Обувь, машину. Что угодно. Я не прячу ничего."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'a7955352-673d-5ff7-bfcc-506079544d1f';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R196' then jsonb_set(r, '{text}', to_jsonb('"— Зоя Михайловна. Да. Делала мне замечание. — Поправляет ручку параллельно калькулятору. — С половины восьмого до половины второго я был там. Я вам это раньше говорил."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'a7955352-673d-5ff7-bfcc-506079544d1f';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R303' then jsonb_set(r, '{text}', to_jsonb('"Данияр поправляет очки.\n— Это не секрет. В четверг в пять он уезжал. Совещания на четверг вечером мы не ставили.\n(пауза)\n— Это знали в офисе, на складе, охрана на КПП."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'a7955352-673d-5ff7-bfcc-506079544d1f';
commit;
select jsonb_array_length(fixed_questions) q, jsonb_array_length(reaction_rules) r from characters where id = 'a7955352-673d-5ff7-bfcc-506079544d1f';
